#include <stdio.h>
#include <string.h>

void reverse(char *s, int left, int right) {
    if (left >= right) {
        return;
    }
    char temp = s[left];
    s[left] = s[right];
    s[right] = temp;
    reverse(s, left + 1, right - 1);
}

int main() {
    char word[] = "recursion";
    reverse(word, 0, strlen(word) - 1);
    printf("%s\n", word);
    return 0;
}
